import{Et as e,L as t,R as n,S as r,V as i,b as a,kt as o,n as s,r as c,wt as l}from"./ui-BBa--tm2.js";import{C as u,c as d,n as f,x as p}from"./queries-Dm1FfXXQ.js";import{t as m}from"./arrow-right-DFMwJQeL.js";import{t as h}from"./lightbulb-DCcgt1sJ.js";import{wt as g}from"./index-DM3ZBqS6.js";import{n as _,r as v}from"./Board-Cm1zaXM_.js";var y={name:`circle`,size:24,node:[[`circle`,{cx:`12`,cy:`12`,r:`10`,key:`1mglay`}]]};y.node;var b=n(y),x=o(e(),1),S=[{id:`start`,title:`Start here`,summary:`Sign in, find your way around, and what the demo hospital is.`,audience:`everyone`,image:`start`,steps:[`Sign in with your own account. In the demo there is one per role, all with password **demo1234**: **manager** (pharmacy manager), **senior** (senior pharmacist), **pharm** (pharmacist) and **view** (can look, cannot change anything) — and the owner account made when the server was set up.`,`What you see depends on your **role**: screens and buttons your role does not allow are not shown. Your role is under your name at the bottom of the menu.`,`The menu on the left has the daily work at the top (**Ward dispensing**, **Daily run**, **Walk-ins**, **Patients**), then the pharmacy's management screens, then **Chat** and **Admin**.`,`Under the hospital name is the **pharmacy** you are working in. Admins can switch pharmacy there; pharmacists work in their own.`,`Press **Ctrl + K** (or the search box at the top) to find any patient or screen by typing part of its name.`,`The bell at the top shows stock alerts: expired batches, items out of stock, batches expiring soon.`,`Everything you change is recorded under your name (the admins can see it in the audit log).`],tips:[`The blue **Demo hospital** ribbon means every patient is made up: try anything, nothing is real.`,`Clinical data (patient and drug names, departments) stays in Arabic, exactly as in the old system.`]},{id:`ward`,title:`Ward dispensing`,summary:`A patient's orders, today's doses, and dispensing with labels.`,audience:`pharmacists`,open:{path:`/`,label:`Ward dispensing`},image:`ward`,steps:[`Pick a patient from the list on the left (filter by department, or type a name or patient ID).`,`The middle shows the patient's **Regular** and **Non-regular** orders (infusions, once only, operations…). Each line has today's dose times: a full dot is dispensed, an empty dot is still to come, orange is late, the red line is now.`,`Click an order to see it on the right. To prescribe, press **Add order**, choose the item, then fill **Qty per dose**, **Order type**, **Frequency**, **Route**, **Duration (days)** (empty = ongoing), **Start date** and **First dose**.`,`The label preview under the form shows exactly what will print. Press **Save order**, or **Dispense & print** to dispense the remaining doses of today now.`,`The **Dispense & return** tab dispenses outside the schedule (a manual dispense) or takes medicine back (a return goes back into stock, into the batch it came from).`,`The **History** tab lists everything dispensed and returned for this patient.`,`The buttons beside the patient's name edit the patient, print the patient label or medication list, load an **order template** or an **operation kit**, or deactivate the patient when they leave.`],tips:[`Stock is taken from the batch that expires first (FEFO), automatically.`,`An order changed after it was dispensed today is not dispensed again by the daily run: you decide.`]},{id:`run`,title:`Daily run`,summary:`All the doses of the medical day for every patient, dispensed and labelled in one go.`,audience:`pharmacists`,open:{path:`/runs`,label:`Daily run`},image:`run`,steps:[`Check the **Medical day** (it runs from 6 AM to 6 AM next morning) and choose **Medication labels** or **Patient labels**.`,`Choose **24 hours** for the whole day, or **Selected times** for, say, the 12 PM round only.`,`Narrow it down if you need to: all patients, one **Department** or one **Patient**, and which order types.`,`Read the **Run preview**: **To dispense**, **Short stock** (not enough on the shelf), **Skipped** (ended, on hold, no dose today) and **Already dispensed**. Untick any line you do not want.`,`Press **Dispense & print**. The labels print in patient order and the stock is updated.`,`**Run history** lists past runs: open one to reprint its labels.`],tips:[`Running the same day twice never dispenses a dose twice: what was already dispensed is shown and left out.`,`A run for a past day asks you to confirm first.`]},{id:`walkin`,title:`Walk-ins`,summary:`Outpatient prescriptions at the counter: type, dispense and print in seconds.`,audience:`pharmacists`,open:{path:`/walkin`,label:`Walk-ins`},image:`walkin`,steps:[`Press **New ticket** (**Alt + N**) and type the **Patient ID** and **Patient name** from the prescription.`,`Add the items: type part of the name or code in the item line. **Enter** moves to the next cell, the arrow keys move between lines.`,`Or choose an **Rx template** (a ready-made prescription such as a gastritis or pain set) and press **Add** to bring in all its lines at once.`,`Check the quantities and the label preview, then **Print** (**F7**), **Dispense** (**F8**) or both (**Dispense & print**, **F9**).`,`**Today's tickets** on the right lists the day's walk-ins: open one to see or reprint it.`],tips:[`The ticket is saved as soon as it has its first item, so nothing is lost if you are interrupted.`]},{id:`patients`,title:`Patients`,summary:`Admit, edit, discharge and bring back patients.`,audience:`pharmacists`,open:{path:`/patients`,label:`Patients`},image:`patients`,steps:[`**New patient**: the hospital patient ID, name and department, then date of birth (children are marked by themselves), coverage, diagnosis and **Alert notes** (allergies, warnings), which print on every label. Choosing an **Operation** adds its kit as orders.`,`**Active** lists the patients on the wards, **Inactive** those who left. **Deactivate patient** when they are discharged; their history is kept.`,`An inactive patient can be restored to a department of your pharmacy, for example when they are readmitted.`,`**Open in Ward dispensing** jumps to the patient's orders.`]},{id:`safety`,title:`Patient safety checks`,summary:`Allergies, interactions, duplicates, dose limits and high-alert medicines.`,audience:`pharmacists`,open:{path:`/safety`,label:`Safety`},image:`safety`,steps:[`Under the patient's name on **Ward dispensing**: sex, age, weight, height and body surface area, and the **allergies**. Click the allergy line to record them: an active ingredient, an item class, or any word in a medicine's name, with the reaction and how severe. Asked and found none? **No known allergies**. Weight, height and sex are in **Edit patient details**.`,`While you write an order, its alerts show at the top of the form. When you save — or load a template or kit, or dispense a walk-in ticket for a hospital patient — the **Safety check** opens if anything was found: read each alert, then **Cancel**, or go ahead.`,`Red (critical: an allergy, a major interaction, a dose above the limit) needs a **reason**; amber (a duplicate, a moderate interaction, a high-alert medicine) needs a confirmation; blue is a note. Every alert you went ahead despite, or cancelled for, is kept in the **Alert log** with your name.`,`High-alert medicines have a red **HIGH ALERT** badge in the order lists. When the hospital switches it on (**Admin → Settings → Patient safety**), a second pharmacist enters their username and password before one goes.`,`The **Safety** screen holds your hospital's own rules: **Interaction rules** (two ingredients or classes, how severe, what to do), and per item **high-alert**, a **tall-man name** for look-alike medicines (for example cefTRIAXone) and **dose limits** per dose, per day and per kg.`],tips:[`No clinical rules come with the system: your pharmacists write them (permission **Maintain clinical safety rules**). The demo has a few examples marked (demo example).`,`Try it on the demo: **مريض تجريبي علي فتحي** is allergic to the digoxin he is on — change that order and save.`]},{id:`stock`,title:`Stock`,summary:`What is on the shelf, deliveries, counts and expiry.`,audience:`pharmacists`,open:{path:`/stock`,label:`Stock`},image:`stock`,steps:[`**On hand** shows every item with its usable quantity, nearest expiry and status. The cards at the top filter it: low, out of stock, expiring, expired.`,`**Receive** enters a delivery: one line per item and batch (batch number, expiry, quantity), then **Save receipt**. Enter in the quantity adds the next line.`,`**Stock count** compares the system balance with what you count on the shelf; type the counted quantities and the differences are corrected, with your reason.`,`**Expiring soon** lists batches expiring within 30, 60, 90 or 180 days, so they can be used or transferred first.`,`**Temporary (TEMP)** stock lets the wards be served before a delivery is entered; replace it with the real batch when it arrives.`],tips:[`Every receipt, count, dispense and return is kept in the batch's stock movements: nothing changes without a record.`]},{id:`barcodes`,title:`Barcodes, recalls and the picking list`,summary:`Scan packs and patient labels, hold or recall a batch, and pick the daily run.`,audience:`pharmacists`,open:{path:`/stock/holds`,label:`Holds and recalls`},image:`barcodes`,steps:[`A barcode scanner types like a keyboard. On **Stock → Receive**, scan each pack into **Scan packs**: the 2D code fills the item, batch and expiry, and every scan of the same pack adds one. A code seen for the first time asks which item it is, once.`,`Scan a **patient label** anywhere and the patient opens on Ward dispensing. Admins add the **Patient ID barcode** box to the labels in **Admin → Labels**. On **Walk-ins** a scanned pack adds its item.`,`In **Dispense & print**, scan the pack you are about to give: it must be the right medicine, not expired and not held. The hospital can make this scan required for high-alert medicines or for every ward dispense (**Admin → Settings → Patient safety**).`,`**Stock → Holds and recalls**: **Hold a batch** puts it in quarantine here; a **recall** holds the lot in every pharmacy and stops it being received. Held stock is never dispensed. **Who received it** lists every patient who got that lot.`,`On **Daily run**, **Picking list** prints what to take off the shelf for the selected orders, with the batches in the order they will be dispensed.`],tips:[`Each item's codes are in its details on **Items** (a pack of another maker or size can have its own).`,`The demo has a recalled lot and a quarantined batch to look at, and every stocked item has a made-up code: type it into Scan packs.`]},{id:`supply`,title:`Supply: transfers, levels and suppliers`,summary:`Ask the main store for stock, send it between pharmacies, set minimum levels, order from suppliers.`,audience:`pharmacists`,open:{path:`/supply`,label:`Supply`},image:`supply`,steps:[`**Supply → Transfers → Ask for stock**: choose the main store (or another pharmacy), the items and quantities. The other pharmacy opens it and presses **Issue**: the earliest expiry leaves its stock first. It is then **On its way** until you press **Receive into our stock** (or **Refuse**, which sends it back).`,`**Send stock** gives stock to another pharmacy without a request, for example near-expiry stock it will use.`,`**Min / max levels**: set a minimum (and maximum) per item. Items below their minimum are listed as a **Suggested request**; **Ask for these** fills a request in one click.`,`**Near expiry** lists batches here that will expire before this pharmacy uses them, and the pharmacies that would use them in time — **Send** moves them there.`,`With purchasing permission: **Suppliers**, **Purchase orders** (draft → send → print), and on **Stock → Receive** the delivery is received against its order, with the price of each line. **Stock value** shows what the stock is worth in EGP; a batch can be **returned to its supplier** from the item's batches on Stock.`,`**Excel**: export the stock list, the item catalogue and the stock value; import a delivery into Receive (use **Template**) and counted quantities into a stock count (**Excel sheet**, fill the Counted column, **Import counts**).`],tips:[`Every quantity that moves between pharmacies is in both batches' stock movements, as a Transfer.`,`The demo's main store holds stock, has a request waiting, and a transfer on its way to OP Pharmacy.`]},{id:`records`,title:`Records: controlled medicines, fridges, carts`,summary:`The registers inspectors ask for: controlled medicines, fridge temperatures, emergency carts, interventions.`,audience:`pharmacists`,open:{path:`/records`,label:`Records`},image:`records`,steps:[`**Records → Controlled medicines** lists the narcotics and psychotropics with their balance here. Open one for its **register**: every movement (received, given to a patient, returned, transferred) with the balance after it — **Print the register** for the book.`,`**Count** a controlled medicine with a second person: enter what is in the cupboard, and the witness signs with their own username and password. A count that differs from the register needs a note (for example a broken ampoule, with its report).`,`**Fridges**: **Read now** records the temperature (and the lowest and highest since the last reading if the fridge has a min / max thermometer). Out of range, say what was done. Each card shows how many readings today against how many it needs; **Log** shows the chart and prints the log.`,`**Emergency carts**: each cart lists what it should hold. **Check it** records what is there, the nearest expiry and the new seal number; with restock ticked, what is missing or expired is given to the cart from this pharmacy's stock. **Print the checklist** for a paper round.`,`**Interventions**: record a problem found in an order, the recommendation and the prescriber's answer — here, or from a patient with the speech-bubble button on their header. The tab shows the acceptance rate.`,`**Accreditation pack** brings the period's records together in one printout: fridge compliance, controlled counts, cart checks, interventions, safety alerts, recalls and expired stock.`],tips:[`Senior pharmacists and managers mark items controlled and add fridges and carts; pharmacists keep the records.`,`In the demo, OP Pharmacy has two fridges read for a month (one went out of range), a cart due for its check, and a dozen interventions.`]},{id:`clinical`,title:`Clinical: verify orders, calculators, leaflets`,summary:`The second pharmacist's check, dose calculators, the discharge leaflet and earlier stays.`,audience:`pharmacists`,open:{path:`/clinical`,label:`Clinical`},image:`clinical`,steps:[`**Clinical → Verify orders** lists new and changed orders waiting for a second pharmacist. Check the item, dose, frequency and route against the patient's weight and allergies, then **Verify** (or tick several and **Verify** them together). You cannot verify an order you wrote.`,`An order not verified yet shows **Not verified** on the patient's order list. If the hospital requires it (Settings → Patient safety), it is not dispensed until verified, and the daily run leaves it out.`,`**Calculators**: dose by weight or body surface area, and creatinine clearance (Cockcroft–Gault). From a patient's header (calculator button) they start with the patient's weight, height, sex and age.`,`On a patient going home: the **leaflet** button prints an Arabic page with each medicine, how much, how often and at what times, with pictures for morning, noon, evening and bedtime. General advice is printed only once your pharmacists have written it (Settings → Patient safety).`,`The **history** button shows the patient's earlier stays and what they were given in each.`,`Also new: **Records → Diversion watch**, **Supply → Min / max levels → Suggest from use**, and **Clinical → ABC × VEN** (which medicines are vital, and where the use goes).`],tips:[`In the demo, four orders at OP Pharmacy wait for verification.`]},{id:`account`,title:`Your account: screen lock, PIN, badge, two-step`,summary:`Lock the screen when you step away, unlock with a PIN, sign in with your badge.`,audience:`everyone`,open:{path:`/account`,label:`Your account`},image:`account`,steps:[`Open **Your account** with the key button by your name. Set a **PIN** (4 to 8 digits) with your password.`,`Step away: press the **lock** button by your name (the screen also locks by itself after a while with nobody using it). Come back: type your PIN or password and **Unlock**.`,`Someone else needs the PC: at the lock screen they scan **their badge** and type their PIN — or press **Switch user**.`,`Your badge is printed by an administrator (Admin → Users → Badge). At the sign-in screen, scan it and type your PIN instead of your username and password.`,`**Two-step sign-in**: Your account → Two-step sign-in → Turn on, scan the QR code with an authenticator app on your phone, type its code, and keep the recovery codes safe. Signing in then asks for the code from your phone too.`],tips:[`Administrators may be required to use two-step sign-in (Settings → Security).`,`In the demo every account's PIN is 1234.`]},{id:`catalogue`,title:`Items, templates and operations`,summary:`The drug catalogue, ready-made prescriptions and operation kits.`,audience:`pharmacists`,open:{path:`/templates`,label:`Templates`},image:`templates`,steps:[`**Items** is the drug catalogue: name, form, unit, active ingredient, storage class. Open an item to see its item card.`,`**Templates → Rx templates** are ready-made walk-in prescriptions: make one from scratch or **From ticket** (from a walk-in you just did).`,`**Templates → Patient order templates** are sets of ward orders (for example a post-operative set) loaded onto a patient in one click.`,`**Operations** lists the operations with their kit for each pharmacy: on a patient, **Load operation kit** adds all of the kit's orders.`]},{id:`reports`,title:`Reports`,summary:`Printable and Excel reports of dispensing and stock.`,audience:`everyone`,open:{path:`/reports`,label:`Reports`},image:`reports`,steps:[`Choose a report: **Dispensing summary**, **Dispensing log**, **Patient totals**, **Item consumption**, **Active medications** or **Stock**.`,`Set the period (**Today**, **Yesterday**, **7 days**, **This month**, or your own dates) and the dispense types.`,`**Print** gives an A4 page with the hospital's header; **Excel (CSV)** opens in Excel.`]},{id:`analytics`,title:`Analytics`,summary:`How the pharmacy is doing, and what to order.`,audience:`everyone`,open:{path:`/analytics`,label:`Analytics`},image:`analytics`,steps:[`Choose the period (a week to a year) and one pharmacy or all of them.`,`The top cards compare the period with the one before: dispensing, patients served, walk-ins, returns, and the critical stock alerts.`,`**Daily dispensing** shows the trend with a forecast for the next two weeks; **Peak hours** shows when the pharmacy is busiest.`,`Further down: departments, staff activity, most consumed items, the **ABC analysis**, returns, the **Expiry radar**, **Reorder suggestions** and **Dead stock**.`,`**Print dashboard** prints it; most tables export to CSV.`],tips:[`The demo hospital has three months of made-up history, so every chart has something to show.`]},{id:`labels`,title:`Labels`,summary:`The old Access labels, exactly — and changing what is on them.`,audience:`admins`,open:{path:`/admin/labels`,label:`Admin → Labels`},steps:[`Labels print exactly like the old Access labels (55 × 55 mm). Every screen that prints shows a live preview you can switch off.`,`To change a label: **Admin → Labels**, pick the label (medication, drip, patient, walk-in, opening, shelf card…).`,`Drag a box to move it, drag its corner to resize it, hide boxes, change the text size, bold and alignment, or **Add a box** for another field or fixed text.`,`**Save for…** this PC (its own label printer), this pharmacy, or all pharmacies.`,`**Reset → Start from the original Access label** and save to go back to the old label at any time.`]},{id:`layout`,title:`Make the screens yours`,summary:`Move and resize panels and table columns, colours and dark mode.`,audience:`everyone`,image:`layout`,steps:[`Press **Edit layout** (the grid button at the top): every panel gets a dashed frame.`,`Drag a panel to move it, drag its edges to resize it, or hide it with the eye. In tables, drag the column chips to reorder or hide columns.`,`**Save for…**: **Only me** (follows you to any PC), or, for admins, **This PC**, **This pharmacy** or **All pharmacies**. **Reset** goes back to the built-in layout.`,`The palette button at the top changes the accent colour, typeface, density and motion; the sun/moon button switches dark mode.`],tips:[`The order of the menu on the left can be changed the same way, in Edit layout.`]},{id:`admin`,title:`Running the system`,summary:`Accounts and roles, pharmacies, settings, backups and updates.`,audience:`admins`,open:{path:`/admin`,label:`Admin`},image:`admin`,steps:[`**Users**: one account per person, with a **role** and their pharmacy. **Reset password** if someone forgets theirs; **Badge** prints their badge card; reset their **two-step sign-in** if they lost their phone. You can give only the roles that do not go beyond your own.`,`**Roles** (the owner only): the owner, pharmacy manager, senior pharmacist, pharmacist and viewer are built in; tick what each may do, or make new roles (**New role**, **Duplicate**). A change applies at once.`,`**Pharmacies & departments** and **Lookups** hold the hospital's lists (routes, frequencies, dose times…).`,`**Settings**: hospital name and report header, announcements to all users, stock thresholds, alerts, label size; **Security**: session length, password rules, the screen lock, badge sign-in and two-step sign-in for administrators.`,`**Backups** run every hour by themselves; each one is opened and checked, and copied to a **second place** (set a USB disk or another PC in Settings → Backups). **Test a restore** once a month. **Back up now** before anything big. **Audit log** shows who changed what, and when.`,`**System health** shows everything that needs attention on one page: backups, disk space, pharmacy PCs, updates, the licence and security.`,`**Network** lists the pharmacy PCs, their sync state, and the database recovery key — write it down once and keep it offline.`,`**Updates**: when a new version is published, **Install update** at a quiet moment; the pharmacy PCs follow by themselves. (The owner, and roles the owner gives “Install updates”.)`]},{id:`network`,title:`Pharmacy PCs and working offline`,summary:`One main server, one PC per pharmacy, and what happens when the network drops.`,audience:`everyone`,steps:[`The **main server** holds the hospital's database. Each **pharmacy PC** is installed with the Pharmacy PC installer and finds the main server on the network by itself.`,`If the network drops, the pharmacy PC keeps working on its own encrypted copy: dispense, print, take walk-ins as usual.`,`When the network is back, the PC sends its work to the main server in the order it was done; the status at the top shows what is still waiting.`,`Both the server and the PCs keep their data encrypted on disk.`]},{id:`leave-demo`,title:`From the demo to real use`,summary:`Removing the demo hospital before the real work starts.`,audience:`admins`,steps:[`The demo hospital is for trying the system and training. Use a spare PC for it if you can.`,`On a PC that ran the demo: uninstall **Hospital Pharmacy** (Windows Settings → Apps), then delete the folder **C:\\HospitalPharmacy\\server\\data** (it holds the demo database).`,`Run the **Main server** installer again and, at the data step, choose **Import from the old Access system** (DataBE.accdb) — or start empty.`,`Make the real accounts in **Admin → Users**: the demo accounts (manager, senior, pharm, view) exist only in the demo.`]}],C=l(),w=`hps.tutorial.done.v1`,T={everyone:{label:`Everyone`,tone:`neutral`},pharmacists:{label:`Pharmacists`,tone:`primary`},admins:{label:`Admins`,tone:`brass`}};function E(){try{let e=JSON.parse(localStorage.getItem(w)??`[]`);return Array.isArray(e)?e.filter(e=>typeof e==`string`):[]}catch{return[]}}function D({text:e}){return(0,C.jsx)(C.Fragment,{children:e.split(/\*\*(.+?)\*\*/g).map((e,t)=>t%2?(0,C.jsx)(`b`,{className:`font-semibold text-ink`,children:e},t):e)})}function O(){let e=p(),{data:n}=d(),[o,l]=u(),[y,O]=(0,x.useState)(E),k=Math.max(0,S.findIndex(e=>e.id===o.get(`lesson`))),A=S[k],j=S[k+1],M=(0,x.useRef)(null),N=e=>{l({lesson:e.id},{replace:!0}),requestAnimationFrame(()=>{let e=M.current?.getBoundingClientRect();e&&(e.top<0||e.top>window.innerHeight*.6)&&M.current.scrollIntoView({block:`start`,behavior:`smooth`})})},P=(e,t)=>{let n=t?[...new Set([...y,e])]:y.filter(t=>t!==e);O(n);try{localStorage.setItem(w,JSON.stringify(n))}catch{}},F=y.includes(A.id),I=!!A.open&&(A.open.path===`/admin/labels`?!!n?.perms.includes(`admin.labels`):A.open.path.startsWith(`/admin`)?f(n):A.open.path===`/reports`||A.open.path===`/analytics`?!!n?.perms.includes(A.open.path.slice(1)):!0);return(0,C.jsxs)(`div`,{className:`pb-6`,children:[(0,C.jsx)(a,{title:`Tutorial`,description:`${S.length} short lessons · ${y.filter(e=>S.some(t=>t.id===e)).length} done`}),(0,C.jsxs)(_,{id:`tutorial`,title:`Tutorial`,children:[(0,C.jsx)(v,{id:`lessons`,title:`Lessons`,w:7,h:70,minW:5,sticky:!0,children:(0,C.jsx)(r,{icon:(0,C.jsx)(g,{}),title:`Lessons`,bodyClassName:`p-2`,children:(0,C.jsx)(`ol`,{className:`flex flex-col gap-0.5`,children:S.map((e,n)=>{let r=e.id===A.id,a=y.includes(e.id);return(0,C.jsx)(`li`,{children:(0,C.jsxs)(`button`,{type:`button`,onClick:()=>N(e),"aria-current":r?`step`:void 0,className:i(`flex w-full items-start gap-2.5 rounded-[12px] px-3 py-2 text-start transition-colors`,r?`bg-primary-soft text-primary-strong`:`hover:bg-sunken`),children:[a?(0,C.jsx)(t,{className:`mt-0.5 size-4 shrink-0 text-ok`}):(0,C.jsx)(`span`,{className:`num mt-px w-4 shrink-0 text-center text-[12.5px] text-muted`,children:n+1}),(0,C.jsxs)(`span`,{className:`min-w-0`,children:[(0,C.jsx)(`span`,{className:`block text-[13.5px] font-semibold`,children:e.title}),(0,C.jsx)(`span`,{className:`block text-[12px] text-muted`,children:T[e.audience].label})]})]})},e.id)})})})}),(0,C.jsx)(v,{id:`lesson`,title:`Lesson`,x:7,w:17,h:100,minW:8,required:!0,children:(0,C.jsx)(`div`,{ref:M,className:`scroll-mt-24`,children:(0,C.jsx)(r,{title:(0,C.jsxs)(`span`,{className:`flex flex-wrap items-center gap-2`,children:[(0,C.jsxs)(`span`,{className:`num text-muted`,children:[k+1,`.`]}),A.title,(0,C.jsx)(s,{tone:T[A.audience].tone,children:T[A.audience].label})]}),subtitle:A.summary,actions:I&&A.open?(0,C.jsxs)(c,{size:`sm`,onClick:()=>e(A.open.path),icon:(0,C.jsx)(m,{className:`size-4`}),children:[`Open `,A.open.label]}):void 0,children:(0,C.jsxs)(`div`,{className:`flex flex-col gap-5`,children:[A.image&&(0,C.jsx)(`img`,{src:`/img/tutorial/${A.image}.jpg`,alt:`The ${A.title} screen`,loading:`lazy`,className:`w-full rounded-[var(--radius-md)] border border-line shadow-panel`,onError:e=>{e.currentTarget.style.display=`none`}},A.image),(0,C.jsx)(`ol`,{className:`flex flex-col gap-3`,children:A.steps.map((e,t)=>(0,C.jsxs)(`li`,{className:`flex gap-3 text-[14px] leading-relaxed text-ink-2`,children:[(0,C.jsx)(`span`,{className:`num grid size-6 shrink-0 place-items-center rounded-full bg-primary-soft text-[12px] font-bold text-primary-strong`,children:t+1}),(0,C.jsx)(`span`,{className:`min-w-0 pt-px`,children:(0,C.jsx)(D,{text:e})})]},t))}),A.tips&&(0,C.jsx)(`div`,{className:`flex flex-col gap-1.5 rounded-[var(--radius-md)] bg-brass-soft px-4 py-3 text-[13.5px] text-brass-ink`,children:A.tips.map((e,t)=>(0,C.jsxs)(`p`,{className:`flex gap-2`,children:[(0,C.jsx)(h,{className:`mt-0.5 size-4 shrink-0`}),(0,C.jsx)(`span`,{children:(0,C.jsx)(D,{text:e})})]},t))}),(0,C.jsxs)(`div`,{className:`flex flex-wrap items-center gap-2 border-t border-line pt-4`,children:[(0,C.jsx)(c,{variant:`ghost`,onClick:()=>P(A.id,!F),icon:F?(0,C.jsx)(t,{className:`size-4 text-ok`}):(0,C.jsx)(b,{className:`size-4`}),children:F?`Done`:`Mark as done`}),j&&(0,C.jsxs)(c,{variant:`primary`,className:`ms-auto`,onClick:()=>{P(A.id,!0),N(j)},icon:(0,C.jsx)(m,{className:`size-4`}),children:[`Next: `,j.title]})]})]})})})})]})]})}export{O as default};